from workflow import *
name='r12_c12_p34';v='v02';f=ROOT/'native/r12_c12_p34_v01.png'
refs=[{'file':str(f),'sha256':sha(f),'role':'complete existing native artwork edit target, object-scale authority'}]+read(ROOT/'references.json')
prompt="""Use case: precise-object-edit. Edit image 1, the fully detailed NATIVE close-up of an existing daylight golden wooden pier, into the SAME 1254-square exact registered crop. Last three images are layout, material, primary painting style only.
Repair the entire long wooden FLOORBOARDS, keeping their existing perspective and number of boards. One short dark groove enters from the left around y300, continues to x230,y250, then fades and ends inside the plank. This is a physical long board boundary and cannot end there. Continue it smoothly to its appropriate genuine existing upper/right boundary endpoint. Connect every long floor groove between real fixed outer endpoints; remove redundant disconnected/fading streaks, forks and abrupt jumps. Rebuild complete coherent board surfaces and grain between boundaries, not a narrow strip. No new grooves or transverse butt seams. The grooves may transition gently in perspective to align, but every boundary must be uninterrupted.
Preserve the actual OUTER 115-pixel neighbor geometry at top and left. Keep the large foreground round GOLD FINIAL, its tiered collar, timber shaft, bright diagonal rail, tiny blue water corner and all their shadows exactly unchanged. Keep their scale and locations. Do not add props or a second sphere. Keep bright hand-painted honey wood and restrained material grain. Opaque full square, no text or UI."""
pf=ROOT/'prompts'/f'{name}_{v}.prompt.txt';assert not pf.exists();pf.write_text(prompt,encoding='utf-8')
write(ROOT/'prompts'/f'{name}_{v}.request.json',{'promptPath':str(pf),'references':refs,'transparent_background':False,'submittedParameters':{'model':None,'quality':None}})
print(json.dumps({'prompt':prompt,'referenced_image_paths':[x['file'] for x in refs],'transparent_background':False}))
